// Turns the recorded reference surface (internal-servers-<build>.json) into
// src/JarvisCode.App/Services/CapturedMcpSchemas.cs, the table the in-process
// MCP tools advertise their input schemas from.
//
// These schemas are the reference's data, not this port's design: the desktop
// declares them as plain JSON Schema literals in its Electron main bundle, and
// a tool that retypes one by hand drifts in a way only a byte comparison
// catches. Same arrangement as Services/CapturedToolDocs.cs for the CLI's tools.
//
//   node gen-captured-mcp-schemas.js internal-servers-1.40609.1.0.json //       android-emulator-1.40609.1.0.json ../../../../src/JarvisCode.App/Services/CapturedMcpSchemas.cs
//
// Takes one or more fixtures because the shell's ten servers and the
// Android-emulator server were recorded by different generators — the latter is
// feature-flagged off in the installed build, so its declaration had to be read
// rather than executed and it carries a single server per file.
//
// Regenerate rather than hand-edit.

const fs = require('fs');

const paths = process.argv.slice(2);
const outPath = paths.pop();
if (paths.length === 0 || !outPath) {
  console.error('usage: node gen-captured-mcp-schemas.js <fixture.json...> <out.cs>');
  process.exit(2);
}

/// A one-server fixture reads as a servers list of length one.
const servers = [];
let build = null;
for (const path of paths) {
  const fixture = JSON.parse(fs.readFileSync(path, 'utf8'));
  build ??= fixture.build;
  if (fixture.servers) {
    servers.push(...fixture.servers);
  } else {
    servers.push({ name: fixture.serverName, wireName: fixture.wireName.split('__')[1], tools: fixture.tools });
  }
}

// The servers whose schemas this port advertises verbatim. Claude_Browser is
// deliberately absent: its preview_start names this app's own launch.json, so
// that server's schemas stay hand-written beside the behaviour they describe.
const CARRIED = new Set([
  'claude-in-chrome',
  'computer-use',
  'ccd_session',
  'ccd_session_mgmt',
  'ccd_directory',
  'terminal',
  'mcp-registry',
  'scheduled-tasks',
  'Claude_Code_Android_Emulator',
  'visualize',
]);

const lines = [];
lines.push('// <auto-generated>');
lines.push(`// Generated from the Captures/Mcp recordings of ${build} by`);
lines.push('// Captures/Mcp/gen-captured-mcp-schemas.js. Regenerate rather than hand-edit.');
lines.push('// </auto-generated>');
lines.push('using System.Collections.Generic;');
lines.push('using System.Text.Json.Nodes;');
lines.push('');
lines.push('namespace JarvisCode.App.Services;');
lines.push('');
lines.push('/// <summary>');
lines.push('/// The in-process MCP servers\' input schemas exactly as the reference desktop');
lines.push(`/// declares them (app.asar ${build}), keyed <c>server/tool</c>.`);
lines.push('///');
lines.push('/// The desktop declares these as plain JSON Schema literals and hands them to');
lines.push('/// the Agent SDK, which converts them to zod and back before the model sees');
lines.push('/// them — a round trip that drops optional properties\' descriptions, the');
lines.push('/// numeric bounds and type unions. This table is the declaration, which is the');
lines.push('/// surface the reference authored and the one its own getAppServersInfo');
lines.push('/// reports; advertising it gives the model more of the contract, never less.');
lines.push('/// </summary>');
lines.push('internal static class CapturedMcpSchemas');
lines.push('{');
lines.push('    /// <summary>The declared schema for one tool, or null when the table has none.</summary>');
lines.push('    internal static JsonObject? Find(string serverName, string toolName) =>');
lines.push('        Raw.TryGetValue(serverName + "/" + toolName, out var json)');
lines.push('            ? (JsonObject)JsonNode.Parse(json)!');
lines.push('            : null;');
lines.push('');
lines.push('    /// <summary>The declared schema for one tool. Throws when the table has none.</summary>');
lines.push('    internal static JsonObject Schema(string serverName, string toolName) =>');
lines.push('        Find(serverName, toolName)');
lines.push('        ?? throw new KeyNotFoundException(');
lines.push('            $"No recorded reference schema for {serverName}/{toolName}. Regenerate ' +
  'CapturedMcpSchemas.cs from the fixture.");');
lines.push('');
lines.push('    private static readonly IReadOnlyDictionary<string, string> Raw =');
lines.push('        new Dictionary<string, string>(System.StringComparer.Ordinal)');
lines.push('        {');

function csRaw(json) {
  // A C# raw string literal: pick a fence longer than any run of quotes inside.
  let longest = 0;
  for (const m of json.match(/"+/g) || []) {
    longest = Math.max(longest, m.length);
  }
  const fence = '"'.repeat(Math.max(3, longest + 1));
  return { fence, json };
}

for (const server of servers) {
  if (!CARRIED.has(server.wireName)) continue;
  for (const tool of server.tools) {
    const json = JSON.stringify(tool.inputSchema, null, 2);
    const { fence } = csRaw(json);
    lines.push(`            ["${server.wireName}/${tool.name}"] = ${fence}`);
    for (const line of json.split('\n')) {
      lines.push(line.length === 0 ? '' : '                ' + line);
    }
    lines.push(`                ${fence},`);
  }
}

lines.push('        };');
lines.push('}');

fs.writeFileSync(outPath, lines.join('\n') + '\n');
console.error('wrote', outPath, lines.length, 'lines');
